            helpCentreURL: "https://advisors.maplesure.com/help"
        };

        // Initialize configuration-dependent content
        document.getElementById('service-line-hours').textContent += portalConfig.serviceLineHours;
        document.getElementById('help-centre-link').setAttribute('href', portalConfig.helpCentreURL);

        // Form and user interaction
        document.getElementById('lookup-member').onclick = function() {
            const memberId = document.getElementById('member-id').value;
            const memberDetails = document.getElementById('member-details');
            memberDetails.textContent = mockMemberData[memberId] || 'Member not found';
        };

        document.getElementById('documents').onchange = function(event) {
            const fileList = document.getElementById('file-list');
            fileList.innerHTML = '';
            for (const file of event.target.files) {
                const listItem = document.createElement('div');
                listItem.textContent = file.name;
                fileList.appendChild(listItem);
            }
        };

        document.getElementById('claim-form').onsubmit = function(event) {
            event.preventDefault(); // Prevent actual form submission
            document.getElementById('claim-form').style.display = 'none';

            // Generate reference number
            const refNo = "MS-" + new Date().getFullYear() + "-08-" + Math.floor(Math.random() * 10000);

            const confirmationPanel = document.getElementById('confirmation');
            confirmationPanel.textContent = `Reference Number: ${refNo} \nStatus: Received`;
            confirmationPanel.style.display = 'block';
        };
    </script>
